export type MarkdownHeading = {
  /** The heading level, from 1 (top level) to 6. */
  depth: number
  /** The plain-text heading content with all inline formatting stripped. */
  value: string
}

/** Matches an ATX heading line such as `## Title` (1 to 6 leading hashes followed by whitespace). */
const ATX_HEADING = /^(#{1,6})[ \t]+(.*)$/

/** Matches trailing closing hashes on an ATX heading, e.g. the ` ##` in `## Title ##`. */
const CLOSING_HASHES = /[ \t]+#+[ \t]*$/

/** Matches a fenced code block delimiter (three or more backticks or tildes, optionally indented). */
const CODE_FENCE = /^ {0,3}(`{3,}|~{3,})/

/** Matches a setext underline made entirely of `=` (depth 1) or `-` (depth 2). */
const SETEXT_UNDERLINE = /^(=+|-+)[ \t]*$/

/** Matches an indented code block line (four spaces or a leading tab). */
const INDENTED_CODE = /^(?: {4}|\t)/

/**
 * Removes inline markdown formatting from a heading value, keeping only the
 * readable text. Bold, italic, inline code, strikethrough, link and image
 * syntax, and raw HTML tags are all stripped.
 *
 * @param text - The raw heading text
 * @returns The text with inline formatting removed
 */
const stripInlineFormatting = (text: string): string =>
  text
    // Images: keep the alt text
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Links: keep the link text
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Inline code
    .replace(/`([^`]+)`/g, '$1')
    // Bold
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    // Strikethrough
    .replace(/~~([^~]+)~~/g, '$1')
    // Italic
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/_([^_]+)_/g, '$1')
    // Raw HTML tags
    .replace(/<[^>]+>/g, '')
    .trim()

/**
 * Parses a markdown string and returns its headings in document order.
 *
 * Both ATX headings (`# Title`) and setext headings (a line of text with a row
 * of `=` or `-` underneath) are recognized. Content inside fenced or indented
 * code blocks is ignored, and inline formatting is stripped from the resulting
 * values so they are ready to display in a navigation sidebar.
 *
 * @param markdown - The markdown string to parse
 * @returns An array of headings, each with a `depth` (1-6) and plain-text `value`
 *
 * @example
 * getMarkdownHeadings('# Getting Started\n## Installation')
 * // Returns:
 * // [
 * //   { depth: 1, value: 'Getting Started' },
 * //   { depth: 2, value: 'Installation' },
 * // ]
 */
export const getMarkdownHeadings = (markdown: string): MarkdownHeading[] => {
  if (!markdown) {
    return []
  }

  // Normalize line endings so Windows (CRLF) input is handled correctly.
  const lines = markdown.split(/\r\n|\r|\n/)
  const headings: MarkdownHeading[] = []

  let inFence = false
  let fenceMarker = ''

  // The previous non-blank line that could serve as the text of a setext
  // heading. It is null after blank lines, code, or lines already consumed.
  let previousLine: string | null = null

  for (const line of lines) {
    const fenceMatch = line.match(CODE_FENCE)

    // Inside a fenced code block: skip everything until the closing fence.
    if (inFence) {
      if (fenceMatch && line.trim()[0] === fenceMarker) {
        inFence = false
        fenceMarker = ''
      }
      previousLine = null
      continue
    }

    // Opening fence: enter the code block and remember its delimiter character.
    if (fenceMatch) {
      inFence = true
      fenceMarker = fenceMatch[1][0]
      previousLine = null
      continue
    }

    // Indented code blocks cannot contain headings and cannot act as setext text.
    if (INDENTED_CODE.test(line)) {
      previousLine = null
      continue
    }

    // ATX heading, e.g. `## Title` or the closing form `## Title ##`.
    const atxMatch = line.match(ATX_HEADING)
    if (atxMatch) {
      const depth = atxMatch[1].length
      const value = stripInlineFormatting(atxMatch[2].replace(CLOSING_HASHES, '').trim())

      headings.push({ depth, value })
      previousLine = null
      continue
    }

    // Setext heading: a row of `=` or `-` directly under a line of text.
    const setextMatch = line.match(SETEXT_UNDERLINE)
    if (setextMatch && previousLine !== null && previousLine.trim() !== '') {
      const depth = setextMatch[1][0] === '=' ? 1 : 2
      const value = stripInlineFormatting(previousLine.trim())

      headings.push({ depth, value })
      previousLine = null
      continue
    }

    // Remember non-blank lines so the next line can turn them into a setext heading.
    previousLine = line.trim() === '' ? null : line
  }

  return headings
}
